def run_port(npz, repo, state_dtype, cmp, want_dtypes):
    """(fixed arm fields, kernel-direct fields, fixed_arm, mods, jax, jnp, meta) -- JAX imported here only."""
    sys.path.insert(0, str(Path(repo) / 'src'))
    import jax
    jax.config.update('jax_enable_x64', True)
    import jax.numpy as jnp
    from gpuwrf.contracts.grid import BCMetadata, DycoreMetrics, GridSpec, Projection, TerrainProvenance, VerticalCoord
    from gpuwrf.contracts.precision import DEFAULT_DTYPES
    from gpuwrf.contracts.state import State, _state_field_shapes
    from gpuwrf.coupling import physics_couplers as pc
    from gpuwrf.physics import thompson_aero_column as aero
    from gpuwrf.contracts.precision import SURFACE_LAYER_CARRY_LEAVES, MYNN_DIAGNOSTIC_LEAVES, MP_RE_DIAGNOSTIC_LEAVES
    from gpuwrf.runtime.operational_mode import STATE_FIELD_ORDER, _enforce_operational_precision
    nz = int(npz['qv'].shape[0])
    eta = jnp.linspace(1.0, 0.0, nz + 1, dtype=jnp.float64)
    projection = Projection('lambert', 28.3, -16.4, 3000.0, 3000.0, 1, 1)
    terrain = TerrainProvenance(source_path='p0c3b', sha256='p0c3b', shape=(1, 1), units='m', projection_transform='native-wrf-lambert', max_elevation_m=0.0, coastline_sanity_check_passed=True)
    metrics = DycoreMetrics.flat(ny=1, nx=1, nz=nz, eta_levels=eta, top_pressure_pa=5000.0, provenance='p0c3b')
    grid = GridSpec(projection, terrain, VerticalCoord('hybrid_eta', nz, 5000.0, eta), BCMetadata('ideal', (), 1, 'linear', True), eta, jnp.zeros((1, 1), jnp.float64), metrics=metrics)
    shapes = _state_field_shapes(grid)

    def dt_of(name):
        if state_dtype == 'fp64':
            return jnp.float64
        try:
            return DEFAULT_DTYPES.dtype_for(name)
        except KeyError:
            return jnp.float64
    col = lambda a: np.asarray(a, np.float64).reshape(-1, 1, 1)
    theta_dry, qv = (col(npz['theta_dry']), col(npz['qv']))
    values = {'theta': theta_dry * (1.0 + cmp.RV_OVER_RD * qv), 'qv': qv, 'qc': col(npz['qc']), 'qr': col(npz['qr']), 'qi': col(npz['qi']), 'qs': col(npz['qs']), 'qg': col(npz['qg']), 'Ni': col(npz['Ni']), 'Nr': col(npz['Nr']), 'Ns': col(npz['Ns']), 'Ng': col(npz['Ng']), 'Nc': col(npz['Nc']), 'nwfa': col(npz['nwfa']), 'nifa': col(npz['nifa']), 'p_total': col(npz['p']), 'ph_total': col(npz['ph']), 'w': col(npz['w'])}
    for name, arr in values.items():
        want = shapes.get(name, shapes['qc'] if name in ('nwfa', 'nifa') else None)
        if want is None or tuple(want) != arr.shape:
            raise Refuse(f'State field {name}: shape {arr.shape} vs contract {want}')
    fields = {name: jnp.zeros(shape, dtype=dt_of(name)) for name, shape in shapes.items()}
    fields.update({name: jnp.asarray(arr, dtype=dt_of(name)) for name, arr in values.items()})
    state = State(**fields).ensure_conditional_leaves(mp_physics=28)
    pass
    if state_dtype == 'fp64':
        redo = {n: jnp.asarray(arr, dtype=jnp.float64) for n, arr in values.items() if getattr(state, n).dtype != jnp.float64}
        if redo:
            state = state.replace(_cast=False, **redo)
        state = _enforce_operational_precision(state, force_fp64=True)
        low = [f for f in STATE_FIELD_ORDER if f not in (*SURFACE_LAYER_CARRY_LEAVES, *MYNN_DIAGNOSTIC_LEAVES, *MP_RE_DIAGNOSTIC_LEAVES) and getattr(state, f, None) is not None and (getattr(state, f).dtype != jnp.float64)]
        if low:
            raise Refuse(f'fp64 arm: leaves not float64 after force_fp64: {low}')
        bad_radii = [f for f in MP_RE_DIAGNOSTIC_LEAVES if getattr(state, f, None) is not None and getattr(state, f).dtype != jnp.float32]
        if bad_radii:
            raise Refuse(f'fp64 arm: WRF REAL radii not float32: {bad_radii}')
    dtypes = {name: str(getattr(state, name).dtype) for name in ('theta', 'qv', 'qc', 'Nc', 'nwfa', 'nifa', 'p_total')}
    if dtypes != want_dtypes:
        raise Refuse(f"state dtype vector {dtypes} != the {state_dtype} arm's {want_dtypes}")
    dt = float(npz['dt'])
    nwfa2d_port = float(npz['nwfa2d'])
    nifa2d_port = float(npz['nifa2d'])
    expected_emissions = tuple((np.asarray([[npz[n]]], np.float32) for n in ('nwfa2d', 'nifa2d')))
    kernel = pc.step_thompson_aero_column_with_precip
    if kernel is not aero.step_thompson_aero_column_with_precip:
        raise Refuse('physics_couplers kernel binding is not thompson_aero_column.step_thompson_aero_column_with_precip')
    flat = lambda a: np.asarray(a, np.float64).reshape(-1)
    p64 = flat(npz['p'])
    pi_port = (np.maximum(p64, 1.0) / float(pc.P0_PA)) ** float(pc.R_D_OVER_CP)

    def fixed_arm():
        seen = {}
        emit = pc.apply_surface_aerosol_emission

        def spy(column, dt_, debug=False):
            out, precip = kernel(column, dt_, debug=debug)
            seen['T_in'], seen['T_out'] = (np.asarray(column.T, np.float64), np.asarray(out.T, np.float64))
            return (out, precip)

        def emission_spy(column, water, dust, dt_):
            for actual, expected in zip((water, dust), expected_emissions):
                np.testing.assert_array_equal(np.asarray(actual), expected)
            seen['emission_calls'] = seen.get('emission_calls', 0) + 1
            return emit(column, water, dust, dt_)
        pc.step_thompson_aero_column_with_precip = spy
        pc.apply_surface_aerosol_emission = emission_spy
        try:
            nxt = pc.thompson_aero_adapter(state, dt, grid)
        finally:
            pc.step_thompson_aero_column_with_precip = kernel
            pc.apply_surface_aerosol_emission = emit
        if 'T_in' not in seen:
            raise Refuse('fixed arm did not reach the aero Thompson kernel')
        assert seen.get('emission_calls') == 1, 'adapter did not consume held original-driver emissions'
        for name, expected in zip(('nwfa2d', 'nifa2d'), expected_emissions):
            np.testing.assert_array_equal(np.asarray(getattr(nxt, name)), expected)
        T_in, T_out = (flat(seen['T_in']), flat(seen['T_out']))
        return {'T': T_out, 'qv': flat(nxt.qv), 'qc': flat(nxt.qc), 'dT': T_out - T_in, 'dtheta_dry': (T_out - T_in) / pi_port, 'theta_m': flat(nxt.theta), 'nc': flat(nxt.Nc), 'nwfa': flat(nxt.nwfa), 'T_in': T_in}
    jax.clear_caches()
    fixed = fixed_arm()
    d = {k: np.asarray(npz['driver_' + k], np.float32).astype(np.float64) for k in DRIVER_FIELDS}
    Tw = d['th'] * d['pii']
    rho_w = 0.622 * d['p'] / (R_DRY * Tw * (d['qv'] + 0.622))
    c1 = lambda a: jnp.asarray(np.asarray(a, np.float64).reshape(1, 1, -1))
    kcol = aero.ThompsonAeroColumnState(c1(d['qv']), c1(d['qc']), c1(d['qr']), c1(d['qi']), c1(d['qs']), c1(d['qg']), c1(d['ni']), c1(d['nr']), c1(d['nc']), c1(d['nwfa']), c1(d['nifa']), c1(Tw), c1(d['p']), c1(rho_w), Ns=c1(npz['Ns']), Ng=c1(npz['Ng']), dz=c1(d['dz8w']), w=c1(d['w']))
    kout, _ = kernel(kcol, dt, debug=False)
    kout = aero.apply_surface_aerosol_emission(kout, jnp.asarray([[float(npz['nwfa2d'])]]), jnp.asarray([[float(npz['nifa2d'])]]), dt)
    kd = {'T': flat(kout.T), 'qv': flat(kout.qv), 'qc': flat(kout.qc), 'nc': flat(kout.Nc), 'nwfa': flat(kout.nwfa)}
    mods = {'aero': aero, 'pc': pc}
    code = {Path(m.__file__).name: sha256_file(m.__file__) for m in (pc, aero)}
    return (fixed, kd, fixed_arm, mods, jax, jnp, {'state_dtypes': dtypes, 'port_code_sha256': code, 'port_nwfa2d': nwfa2d_port, 'port_nifa2d': nifa2d_port, 'emission_source': 'frozen original-driver held inputs; consumption/preservation checked'})
